    font-family:
        "HarmonyOS Sans SC",
        sans-serif;

    font-weight: 700;
}


/* ============================================================
   12. 行内代码
   Cascadia Code
   ============================================================ */

:is(.markdown-reading-view, .markdown-source-view.mod-cm6) .markdown-rendered code,
.markdown-source-view.mod-cm6 .cm-inline-code {

    font-family:
        "Cascadia Code Local",
        "Cascadia Code",
        Consolas,
        monospace;
}


/* ============================================================
   13. 代码块
   Cascadia Code
   ============================================================ */

:is(.markdown-reading-view, .markdown-source-view.mod-cm6) .markdown-rendered :is(pre, pre code),
.markdown-source-view.mod-cm6 .HyperMD-codeblock {

    font-family:
        "Cascadia Code Local",
        "Cascadia Code",
        Consolas,
        monospace;
}
/* ============================================================
   正文排版
   - 首行缩进 2 个中文字符
   - 两端对齐
   - 紧凑段落间距
   ============================================================ */


/* ============================================================
   01. 阅读模式
   ============================================================ */

/* Indentation belongs to prose, not lists, quotes, tables, diagrams or media. */
:is(.markdown-reading-view, .markdown-source-view.mod-cm6) .markdown-rendered
p:not(:where(li p, blockquote p, .callout p, td p, th p, foreignObject p,
    .mermaid p, .block-language-mermaid p, .block-language-table p,
    .cp-cell-markdown p, .math p)):not(:has(img, video, audio, iframe, svg, canvas,
    .internal-embed, .image-embed, .markdown-embed)) {
    /* 首行缩进两个中文字符 */
    text-indent: 2em !important;

    /* 两端对齐 */
    text-align: justify !important;
    text-justify: inter-character;

    /* 行高 */
    line-height: var(--typography-body-line-height);

    /* 段落间距 */
    margin-top: 0 !important;
    margin-bottom: 0.35em !important;
}

/* Mermaid uses HTML paragraphs inside SVG foreignObject labels. */
:is(.markdown-reading-view, .markdown-source-view.mod-cm6) .markdown-rendered :is(.mermaid, .block-language-mermaid) foreignObject p {
    text-indent: 0 !important;
    text-align: center !important;
    text-justify: auto !important;
    line-height: 1.5 !important;
    margin: 0 !important;
    letter-spacing: normal !important;
    word-spacing: normal !important;
}

/* 段落紧跟列表时，消除列表自带的 margin-top，避免间距过大 */
:is(.markdown-reading-view, .markdown-source-view.mod-cm6) .markdown-rendered p + :is(ul, ol) {
    margin-top: 0 !important;
}

/* 列表紧跟段落时，消除列表的 margin-bottom，保持紧凑 */
:is(.markdown-reading-view, .markdown-source-view.mod-cm6) .markdown-rendered :is(ul, ol) + p {
    margin-top: 0 !important;
}

/* 阅读模式：统一收紧列表自身的上下间距 */
:is(.markdown-reading-view, .markdown-source-view.mod-cm6) .markdown-rendered :is(ul, ol) {
    margin-top: 0.2em !important;
    margin-bottom: 0.2em !important;
}

/* 阅读模式：列表项之间也收紧 */
:is(.markdown-reading-view, .markdown-source-view.mod-cm6) .markdown-rendered li {
    margin-top: 0 !important;
    margin-bottom: 0 !important;
}


/* ============================================================
   02. 编辑模式 / Live Preview
   ============================================================ */

/* A physical source line is not necessarily a new Markdown paragraph. */
.markdown-source-view.mod-cm6 .cm-content > .cm-line {
    --typography-line-indent: 0em;
}

/* A leading .cm-gap belongs to off-screen text, not a document start. */
.markdown-source-view.mod-cm6 .cm-content > .cm-line:first-child,
.markdown-source-view.mod-cm6 .cm-content > :is(
    .cm-line:has(> br:only-child),
    .HyperMD-header,
    .HyperMD-codeblock-end,
    .HyperMD-hr,
    .HyperMD-table-row,
    .HyperMD-frontmatter,
    .cm-embed-block
) + .cm-line {
    --typography-line-indent: 2em;
}

.markdown-source-view.mod-cm6
.cm-line:not(.HyperMD-header, .HyperMD-list-line, .HyperMD-quote,
    .HyperMD-codeblock, .HyperMD-codeblock-bg, .HyperMD-frontmatter,
    .HyperMD-table-row, .HyperMD-hr, .HyperMD-callout):not(:has(.image-wrapper,
    .image-embed, .internal-embed, .cm-embed-block,
    .math-block, .cm-hmd-frontmatter)) {

    /* 只缩进段落首行；一次回车产生的续行不重新缩进。 */
    text-indent: var(--typography-line-indent, 0em) !important;

    /* 两端对齐 */
    text-align: justify !important;
    text-justify: inter-character;
}


/* ============================================================
   03. 编辑模式：缩小段落空白行
   ============================================================ */

.markdown-source-view.mod-cm6
.cm-line:not(.HyperMD-header, .HyperMD-list-line, .HyperMD-quote,
    .HyperMD-codeblock, .HyperMD-codeblock-bg, .HyperMD-frontmatter):has(> br:only-child) {
    line-height: 0.65em !important;
    min-height: 0.65em !important;
}

